import React, { createContext, useEffect, useState, useMemo } from "react";

export const ShopContext = createContext(null);

const ShopContextProvider = (props) => {
    const [allProducts, setAllProducts] = useState([]);
    const [cartItems, setCartItems] = useState({});

    useEffect(() => {
        fetch('http://localhost:4000/allproducts')
            .then((response) => {
                if (!response.ok) throw new Error('Failed to fetch products');
                return response.json();
            })
            .then((data) => {
                setAllProducts(data);
                const cart = data.reduce((acc, product) => ({ ...acc, [product.id]: 0 }), {});
                setCartItems(cart);
            })
            .catch((error) => console.error('Error fetching products:', error));
    }, []);

    const addToCart = (itemId) => {
        setCartItems((prev) => ({ ...prev, [itemId]: prev[itemId] + 1 }));
    };

    const deleteFromCart = (itemId) => {
        setCartItems((prev) => ({ ...prev, [itemId]: Math.max(0, prev[itemId] - 1) }));
    };

    const getTotalCartAmount = useMemo(() => {
        return Object.entries(cartItems).reduce((total, [itemId, quantity]) => {
            const item = allProducts.find((product) => product.id === Number(itemId));
            return item ? total + item.new_price * quantity : total;
        }, 0);
    }, [cartItems, allProducts]);

    const getTotalCartItems = useMemo(() => {
        return Object.values(cartItems).reduce((total, quantity) => total + quantity, 0);
    }, [cartItems]);

    const contextValue = {
        allProducts,
        cartItems,
        addToCart,
        deleteFromCart,
        getTotalCartAmount,
        getTotalCartItems,
    };

    return <ShopContext.Provider value={contextValue}>{props.children}</ShopContext.Provider>;
};

export default ShopContextProvider;
